/**
 * Built-in text enhancer (inference only, no dependencies).
 *
 * Pipeline per pixel luminance:
 *   1. Unsharp mask (separable Gaussian, edge-clamped) — same as the Python trainer.
 *   2. A tiny residual CNN (3 convolutions, 6 hidden channels) learns a correction on top,
 *      which sharpens blurred or faded text and suppresses noise.
 *
 * The weights are generated by tools/text-enhancer/train_text_enhancer.py.
 * Colour is preserved by scaling each RGB channel by the luminance ratio, so
 * coloured documents keep their hue.
 */
import model from './model/text-enhancer.js';

// Correction is applied only where local detail exists (text edges). Flat areas
// such as plain paper or grey shadows are left exactly as they are.
const GATE_SCALE = 0.01;
const LUMA_FLOOR = 0.02;   // below this, the luminance ratio is unreliable
const RATIO_MIN = 0.6;     // keeps near-black pixels from changing hue
const RATIO_MAX = 1.8;

function clamp01(value) {
  return value < 0 ? 0 : value > 1 ? 1 : value;
}

function gaussianKernel(sigma) {
  const radius = Math.ceil(3 * sigma);
  const kernel = new Float32Array(2 * radius + 1);
  let total = 0;
  for (let k = -radius; k <= radius; k += 1) {
    const value = Math.exp(-(k * k) / (2 * sigma * sigma));
    kernel[k + radius] = value;
    total += value;
  }
  for (let k = 0; k < kernel.length; k += 1) kernel[k] /= total;
  return kernel;
}

/**
 * Separable Gaussian on a grayscale plane with edge-replicated borders. The source is
 * copied once into a padded buffer, so the inner loops need no bounds checks.
 */
function blurGray(source, width, height, sigma) {
  const kernel = gaussianKernel(sigma);
  const radius = (kernel.length - 1) >> 1;
  const paddedWidth = width + 2 * radius;
  const paddedHeight = height + 2 * radius;
  const padded = new Float32Array(paddedWidth * paddedHeight);
  for (let y = 0; y < paddedHeight; y += 1) {
    const sy = Math.min(height - 1, Math.max(0, y - radius)) * width;
    for (let x = 0; x < paddedWidth; x += 1) {
      padded[y * paddedWidth + x] = source[sy + Math.min(width - 1, Math.max(0, x - radius))];
    }
  }
  const horizontal = new Float32Array(width * paddedHeight);
  for (let y = 0; y < paddedHeight; y += 1) {
    const row = y * paddedWidth;
    for (let x = 0; x < width; x += 1) {
      let sum = 0;
      for (let k = 0; k < kernel.length; k += 1) sum += kernel[k] * padded[row + x + k];
      horizontal[y * width + x] = sum;
    }
  }
  const out = new Float32Array(width * height);
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      let sum = 0;
      for (let k = 0; k < kernel.length; k += 1) sum += kernel[k] * horizontal[(y + k) * width + x];
      out[y * width + x] = sum;
    }
  }
  return out;
}

/** Unsharp mask on a grayscale plane in 0..1 (same as the trainer's sharpen). */
function sharpenGray(source, width, height, sigma, amount) {
  const blur = blurGray(source, width, height, sigma);
  const out = new Float32Array(width * height);
  for (let i = 0; i < out.length; i += 1) out[i] = clamp01(source[i] + amount * (source[i] - blur[i]));
  return out;
}

/**
 * Copy the outermost real pixels into the border ring of a padded plane.
 * This is the edge-replicate padding used during training.
 */
function replicateBorder(plane, paddedWidth, width, height) {
  const last = paddedWidth * (height + 1);
  for (let x = 1; x <= width; x += 1) {
    plane[x] = plane[paddedWidth + x];
    plane[last + x] = plane[last - paddedWidth + x];
  }
  for (let y = 0; y <= height + 1; y += 1) {
    const row = y * paddedWidth;
    plane[row] = plane[row + 1];
    plane[row + width + 1] = plane[row + width];
  }
}

/**
 * 3x3 convolution on padded planes. Each plane is (width + 2) x (height + 2); its
 * border ring is filled by replicating the nearest real pixel before the next layer.
 */
function convolve(inputs, layer, paddedWidth, width, height, relu) {
  const [outChannels, inChannels] = layer.shape;
  const weight = layer.weight;
  const bias = layer.bias;
  const offsets = [];
  for (let dy = 0; dy < 3; dy += 1) {
    for (let dx = 0; dx < 3; dx += 1) offsets.push((dy - 1) * paddedWidth + (dx - 1));
  }
  const outputs = [];
  for (let o = 0; o < outChannels; o += 1) {
    const out = new Float32Array(paddedWidth * (height + 2));
    const bo = bias[o];
    for (let y = 1; y <= height; y += 1) {
      for (let x = 1; x <= width; x += 1) {
        const p = y * paddedWidth + x;
        let acc = bo;
        for (let c = 0; c < inChannels; c += 1) {
          const plane = inputs[c];
          const base = (o * inChannels + c) * 9;
          for (let k = 0; k < 9; k += 1) acc += weight[base + k] * plane[p + offsets[k]];
        }
        out[p] = relu && acc < 0 ? 0 : acc;
      }
    }
    if (!relu) {
      outputs.push(out);
      continue;
    }
    replicateBorder(out, paddedWidth, width, height);
    outputs.push(out);
  }
  return outputs;
}

/** Enhance a grayscale plane (values 0..1). Returns a new Float32Array of the same size. */
export function enhanceGray(gray, width, height, weights = model) {
  const { sigma, amount } = weights.sharpen;
  const sharp = sharpenGray(gray, width, height, sigma, amount);
  const detailBlur = blurGray(sharp, width, height, sigma);
  const paddedWidth = width + 2;
  const input = new Float32Array(paddedWidth * (height + 2));
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) input[(y + 1) * paddedWidth + x + 1] = sharp[y * width + x];
  }
  replicateBorder(input, paddedWidth, width, height);
  const [first, second, last] = weights.layers;
  const hidden1 = convolve([input], first, paddedWidth, width, height, true);
  const hidden2 = convolve(hidden1, second, paddedWidth, width, height, true);
  const residual = convolve(hidden2, last, paddedWidth, width, height, false)[0];

  const out = new Float32Array(width * height);
  for (let y = 0; y < height; y += 1) {
    for (let x = 0; x < width; x += 1) {
      const index = y * width + x;
      const p = (y + 1) * paddedWidth + x + 1;
      const full = clamp01(input[p] + residual[p]);
      const gate = Math.min(1, Math.abs(sharp[index] - detailBlur[index]) / GATE_SCALE);
      out[index] = clamp01(sharp[index] + (full - sharp[index]) * gate);
    }
  }
  return out;
}

/**
 * Enhance an RGBA buffer in place of the original. `mix` (0..1) blends the
 * enhanced result with the input, so the cleanup slider still controls strength.
 */
export function enhanceRgba(rgba, width, height, mix = 1) {
  const pixels = width * height;
  const luma = new Float32Array(pixels);
  for (let i = 0; i < pixels; i += 1) {
    const o = i * 4;
    luma[i] = (0.299 * rgba[o] + 0.587 * rgba[o + 1] + 0.114 * rgba[o + 2]) / 255;
  }
  const enhanced = enhanceGray(luma, width, height);
  const out = new Uint8ClampedArray(rgba.length);
  const amount = clamp01(mix);
  for (let i = 0; i < pixels; i += 1) {
    const o = i * 4;
    const y = luma[i];
    let ratio = y > LUMA_FLOOR ? enhanced[i] / y : 1;
    ratio = ratio < RATIO_MIN ? RATIO_MIN : ratio > RATIO_MAX ? RATIO_MAX : ratio;
    const scale = 1 + amount * (ratio - 1);
    out[o] = rgba[o] * scale;
    out[o + 1] = rgba[o + 1] * scale;
    out[o + 2] = rgba[o + 2] * scale;
    out[o + 3] = 255;
  }
  return out;
}
